import time

def retry(fn, tries=3, base_delay=0.5):
    last = None
    for i in range(tries):
        try:
            return fn()
        except Exception as e:
            last = e
            time.sleep(base_delay * (2 ** i))
    raise last

def test_retry_succeeds():
    calls = []
    def flaky():
        calls.append(1)
        if len(calls) < 2:
            raise ValueError('boom')
        return 'ok'
    assert retry(flaky) == 'ok'
